      <radialGradient id="ripple-mud-White" cx="32%" cy="24%" r="76%">
        <stop offset="0" stop-color="#ffffff"/><stop offset=".36" stop-color="#fff8ec"/>
        <stop offset=".72" stop-color="#f0dfc0"/><stop offset="1" stop-color="#c8ac7c"/>
      </radialGradient>
